ALTER TABLE starter_content_catalog ADD COLUMN category VARCHAR(64) NOT NULL DEFAULT 'Science';
UPDATE starter_content_catalog SET category=CASE
 WHEN content_key LIKE 'starter-solar-%' THEN 'Space'
 WHEN content_key LIKE 'starter-moon-%' OR content_key='starter-moonlight' THEN 'Moon'
 WHEN content_key LIKE 'starter-water-%' OR content_key IN ('starter-water-cycle','starter-ice-density','starter-ocean-water') THEN 'Water'
 WHEN content_key LIKE 'starter-weather-%' THEN 'Weather'
 WHEN content_key LIKE 'starter-life-%' OR content_key='starter-photosynthesis' THEN 'Biology'
 WHEN content_key LIKE 'starter-geo-%' THEN 'Geology'
 WHEN content_key LIKE 'starter-physics-%' OR content_key IN ('starter-gravity','starter-sound-vibrations') THEN 'Physics'
 WHEN content_key LIKE 'starter-earth-%' THEN 'Earth'
 ELSE 'Science' END;

